# Try mirroring rows 3 and 4 within their regions
grid = [
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 8, 9, 8, 9, 6, 9, 8, 7, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 8, 8, 3, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9]
]

# Region: rows 3-4, cols 9-16 (within each region horizontally)
# Middle column of region is col 12.5, so reflect around that point

output = [[None]*len(grid[0]) for _ in range(len(grid))]

for r in range(len(grid)):
    if r == 3:
        # Row 3: mirror the pattern within cols 9-16
        row_content = list(range(9, 17))
        values = []
        for i in range(9, 17):
            values.append(grid[r][i])
        reversed_values = values[::-1]
        for i in range(9, 17):
            output[r][i] = reversed_values[i - 9]
        for c in range(0, 9):
            output[r][c] = grid[r][c]
        for c in range(17, len(grid[0])):
            output[r][c] = grid[r][c]
    elif r == 4:
        # Same for row 4
        for i in range(9, 17):
            values.append(grid[r][i])
        reversed_values = values[::-1]
        for i in range(9, 17):
            output[r][i] = reversed_values[i - 9]
        for c in range(0, 9):
            output[r][c] = grid[r][c]
        for c in range(17, len(grid[0])):
            output[r][c] = grid[r][c]
    else:
        # Copy as-is
        output[r] = grid[r][:]

print("Mirrored rows:")
for row in output:
    print(row)

